+++ b/src/features/attendance.js
@@ -0,0 +1,12 @@
+import { positiveInteger } from "../lib/validation.js";
+import { buildRoster } from "./roster.js";
+
+export function summarizeAttendance(event, signups) {
+  const capacity = positiveInteger(event?.capacity);
+  const unique = buildRoster(signups).length;
+  return {
+    confirmed: Math.min(unique, capacity),
+    remaining: Math.max(capacity - unique, 0),
+    waitlisted: Math.max(unique - capacity, 0),
+  };
+}

